Link: https://patch.msgid.link/20260408121252.2249051-12-dhowells@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function `rxkad_decrypt_ticket()` fails to check the return value of `crypto_skcipher_decrypt()`. When decryption fails (e.g., due to a non-block-aligned ticket length), the function still parses the buffer as plaintext, allowing an attacker to control the ticket content and potentially exploit the system.

Here is the patch:
  */
 static int rxkad_decrypt_ticket(struct rxrpc_connection *conn,
 				struct key *server_key,
 				struct sk_buff *skb,
 				void *ticket, size_t ticket_len,
 				struct rxrpc_crypt *_session_key,
 				time64_t *_expiry)
 {
 	struct skcipher_request *req;
 	struct rxrpc_crypt iv, key;
 	struct scatterlist sg[1];
 	struct in_addr addr;
 	unsigned int life;
 	time64_t issue, now;
+	int ret;
 	bool little_endian;
 	u8 *p, *q, *name, *end;

 	_enter("{%d},{%x}", conn->debug_id, key_serial(server_key));

 	*_expiry = 0;

 	ASSERT(server_key->payload.data[0] != NULL);
 	ASSERTCMP((unsigned long) ticket & 7UL, ==, 0);

 	memcpy(&iv, &server_key->payload.data[2], sizeof(iv));

 	req = skcipher_request_alloc(server_key->payload.data[0], GFP_NOFS);
 	if (!req)
 		return -ENOMEM;

 	sg_init_one(&sg[0], ticket, ticket_len);
 	skcipher_request_set_callback(req, 0, NULL, NULL);
 	skcipher_request_set_crypt(req, sg, sg, ticket_len, iv.x);
-	crypto_skcipher_decrypt(req);
+	ret = crypto_skcipher_decrypt(req);
 	skcipher_request_free(req);
+	if (ret < 0)
+		return rxrpc_abort_conn(conn, skb, RXKADBADTICKET, -EPROTO,
+					rxkad_abort_resp_tkt_short);

 	p = ticket;
 	end = p + ticket_len;

 #define Z(field, fieldl)						\
 	({								\
 		u8 *__str = p;						\
 		q = memchr(p, 0, end - p);				\
 		if (!q || q - p > field##_SZ)				\
 			return rxrpc_abort_conn(			\
 				conn, skb, RXKADBADTICKET, -EPROTO,	\
 				rxkad_abort_resp_tkt_##fieldl);		\
 		for (; p < q; p++)					\
 			if (!isprint(*p))				\
 				return rxrpc_abort_conn(		\
 					conn, skb, RXKADBADTICKET, -EPROTO, \
 					rxkad_abort_resp_tkt_##fieldl);	\
 		p++;							\
 		__str;							\
 	})

 	/* extract the ticket flags */
 	_debug("KIV FLAGS: %x", *p);
 	little_endian = *p & 1;
 	p++;

 	/* extract the authentication name */
 	name = Z(ANAME, aname);
 	_debug("KIV ANAME: %s", name);

 	/* extract the principal's instance */
 	name = Z(INST, inst);
 	_debug("KIV INST : %s", name);

 	/* extract the principal's authentication domain */
 	name = Z(REALM, realm);
 	_debug("KIV REALM: %s", name);

 	if (end - p < 4 + 8 + 4 + 2)
 		return rxrpc_abort_conn(conn, skb, RXKADBADTICKET, -EPROTO,
 					rxkad_abort_resp_tkt_short);

 	/* get the IPv4 address of the entity that requested the ticket */
 	memcpy(&addr, p, sizeof(addr));
 	p += 4;
 	_debug("KIV ADDR : %pI4", &addr);

 	/* get the session key from the ticket */
 	memcpy(&key, p, sizeof(key));
 	p += 8;
 	_debug("KIV KEY  : %08x %08x", ntohl(key.n[0]), ntohl(key.n[1]));
 	memcpy(_session_key, &key, sizeof(key));

 	/* get the ticket's lifetime */
 	life = *p++ * 5 * 60;
 	_debug("KIV LIFE : %u", life);

 	/* get the issue time of the ticket */
 	if (little_endian) {
 		__le32 stamp;
 		memcpy(&stamp, p, 4);
 		issue = rxrpc_u32_to_time64(le32_to_cpu(stamp));
 	} else {
 		__be32 stamp;
 		memcpy(&stamp, p, 4);
 		issue = rxrpc_u32_to_time64(be32_to_cpu(stamp));
 	}
 	p += 4;
 	now = ktime_get_real_seconds();
 	_debug("KIV ISSUE: %llx [%llx]", issue, now);

 	/* check the ticket is in date */
 	if (issue > now)
 		return rxrpc_abort_conn(conn, skb, RXKADNOAUTH, -EKEYREJECTED,
 					rxkad_abort_resp_tkt_future);
 	if (issue < now - life)
 		return rxrpc_abort_conn(conn, skb, RXKADEXPIRED, -EKEYEXPIRED,
 					rxkad_abort_resp_tkt_expired);

 	*_expiry = issue + life;

 	/* get the service name */
 	name = Z(SNAME, sname);
 	_debug("KIV SNAME: %s", name);

 	/* get the service instance name */
 	name = Z(INST, sinst);
 	_debug("KIV SINST: %s", name);
 	return 0;
 }



